INSERT INTO `SmModuleSql` (`ID`, `CreatedBy`, `CreatedTime`, `UpdateBy`, `UpdateTime`, `ImportDataId`, `ModificationNum`, `Tag`, `GroupId`, `CompanyId`, `ModuleId`, `PrimaryTableName`, `TableNames`, `TableAliasNames`, `PrimaryKey`, `SqlSelect`, `SqlSelectBrw`, `JoinType`, `SqlJoinTable`, `SqlJoinTableAlias`, `SqlJoinCondition`, `SqlDefaultCondition`, `SqlRecycleCondition`, `SqlQueryCondition`, `DefaultSortField`, `DefaultSortDirection`, `GroupBy`, `Description`, `FullSql`, `AuditStatus`, `Remark`, `IsActive`, `IsDeleted`, `CurrentNode`, `ID1`)
VALUES
('495c513a-ce11-47f3-8bef-3899528480d1', NULL, '2026-08-18 06:15:04.163000', NULL, NULL, NULL, 0, 1, NULL, NULL, '7eb69473-cb1a-4d62-a182-041213baa53e', 'AgAgentDefinition', 'AgAgentDefinition', 'A', 'ID', 'SELECT A.*', 'SELECT A.*', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'CreatedTime', 'DESC', NULL, 'Agent Definition 管理列表，发布与生命周期操作由 Agent API 完成。', 'SELECT A.ID,A.Code,A.Name,A.Description,A.RuntimeStatus,A.LogicalRevision,A.CreatedTime,A.UpdateTime,A.Code AS DELETE_CONFIRM_MSG,(SELECT V.Label FROM AgAgentVersion V WHERE V.AgentId=A.ID AND V.IsDraft=0 AND V.IsDeleted=0 ORDER BY V.Ordinal DESC,V.ID DESC LIMIT 1) AS CurrentPublishedLabel FROM AgAgentDefinition A WHERE A.IsDeleted=0', 'Add', NULL, NULL, 0, NULL, NULL),
('a90c0211-7fd4-498a-a435-c5060fb1e52e', NULL, '2026-08-19 09:52:13.123000', NULL, NULL, NULL, 0, 1, NULL, NULL, '6354b334-06d7-43a8-874c-04a19e2449e7', 'AgSkillDefinition', 'AgSkillDefinition', 'A', 'ID', 'SELECT A.*', 'SELECT A.*', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'CreatedTime', 'DESC', NULL, 'Skill 通用管理列表；基础信息、Draft 文件、发布和归档操作由 Agent API 完成。', 'SELECT A.ID,A.Code,A.Name,A.Description,A.Category,A.Status,A.DraftRevision,(SELECT V.Label FROM AgSkillVersion V WHERE V.SkillId=A.ID AND V.IsDeleted=0 ORDER BY V.Ordinal DESC,V.ID DESC LIMIT 1) AS CurrentPublishedLabel,(SELECT COUNT(1) FROM AgSkillVersion V WHERE V.SkillId=A.ID AND V.IsDeleted=0) AS PublishedVersionCount,A.CreatedTime,A.UpdateTime FROM AgSkillDefinition A WHERE A.IsDeleted=0', 'Add', NULL, NULL, 0, NULL, NULL),
('4d47d72a-07b9-4646-acd8-8f5543a5761c', NULL, '2026-08-19 03:35:47.510000', NULL, NULL, NULL, 0, 1, NULL, NULL, '78bb3d15-24a1-42cc-affe-37fe47131170', 'AgMcpServerDefinition', 'AgMcpServerDefinition', 'A', 'ID', 'SELECT A.*', 'SELECT A.*', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'CreatedTime', 'DESC', NULL, 'MCP Server 通用管理列表；配置、同步、启停、归档及工具风险操作由 Agent API 完成。', 'SELECT A.ID,A.Code,A.Name,A.Description,A.Transport,CASE WHEN A.Transport=''Stdio'' THEN A.Command ELSE A.Endpoint END AS ConnectionTarget,(SELECT COUNT(1) FROM AgMcpToolVersion T WHERE T.ServerId=A.ID AND T.CurrentOrdinal IS NOT NULL AND T.IsDeleted=0) AS CurrentToolCount,A.Status,A.LogicalRevision,A.LastSyncedAtUtc,A.CreatedTime,A.UpdateTime FROM AgMcpServerDefinition A WHERE A.IsDeleted=0', 'Add', NULL, NULL, 0, NULL, NULL),
('3d427005-756c-472e-a292-0d34f3a112c7', NULL, '2026-09-09 06:54:11.183000', NULL, NULL, NULL, 0, 1, NULL, NULL, 'c37d1814-0ba2-47df-9428-51c71f86a1f0', 'AgModelConfig', 'AgModelConfig', 'A', 'ID', 'SELECT A.ID,A.ProfileCode,A.DisplayName,A.Provider,A.Endpoint,A.ModelName,A.Enabled,A.TimeoutSeconds,A.EnableThinking,A.CredentialRevision,A.LogicalRevision,A.CreatedTime,A.UpdateTime', 'SELECT A.ID,A.ProfileCode,A.DisplayName,A.Provider,A.Endpoint,A.ModelName,A.Enabled,A.TimeoutSeconds,A.EnableThinking,A.CredentialRevision,A.LogicalRevision,A.CreatedTime,A.UpdateTime', NULL, NULL, NULL, NULL, 'A.IsDeleted=0', NULL, NULL, 'CreatedTime', 'DESC', NULL, '模型配置只读列表；不输出 API 密钥密文，不接入模型运行或保存接口。', 'SELECT A.ID,A.ProfileCode,A.DisplayName,A.Provider,A.Endpoint,A.ModelName,A.Enabled,A.TimeoutSeconds,A.EnableThinking,A.CredentialRevision,A.LogicalRevision,A.CreatedTime,A.UpdateTime FROM AgModelConfig A WHERE A.IsDeleted=0', 'Add', NULL, NULL, 0, NULL, NULL)
